-- Once de Oro · paso a manager de fútbol
-- Ejecútalo una vez en Supabase → SQL Editor → New query → Run.
-- OJO: borra los equipos de fantasy, las jornadas jugadas y los resultados cargados,
-- y empieza una temporada nueva de manager desde la jornada 1. Las cuentas de usuario y los admins se mantienen.

-- Cada mánager dirige un club y no puede haber dos mánagers en el mismo club.
alter table public.managers add column if not exists club text;
delete from public.managers;
delete from public.jornadas;
delete from public.reales;
create unique index if not exists managers_club_unico on public.managers(club);

